-- ============================================
-- LUMA — Thème 11 : 3e scénario COURT x4 — Discuter avec un artiste local
-- ============================================


update scenarios set content = '{"characters": {"artist": "l''artiste"}, "start_node": "n1", "nodes": {"n1": {"speaker": "artist", "text": "Hi there! Feel free to look around, everything here is handmade.", "text_fr": "Salut ! N''hésitez pas à regarder, tout ici est fait main.", "choices": [{"text": "These paintings are beautiful. What inspires your work?", "text_fr": "Ces peintures sont magnifiques. Qu''est-ce qui inspire votre travail ?", "next": "n2"}, {"text": "How long have you been creating art like this?", "text_fr": "Depuis combien de temps créez-vous ce genre d''art ?", "next": "n2b"}]}, "n2": {"speaker": "artist", "text": "Mostly nature and music, actually — festivals like this one inspire a lot of my color choices.", "text_fr": "Surtout la nature et la musique, en fait — des festivals comme celui-ci inspirent beaucoup mes choix de couleurs.", "choices": [{"text": "That makes sense, the energy here is incredible.", "text_fr": "Ça se comprend, l''énergie ici est incroyable.", "next": "n3"}]}, "n2b": {"speaker": "artist", "text": "About eight years now, started as a hobby and slowly became my full-time passion.", "text_fr": "Environ huit ans maintenant, ça a commencé comme un hobby et c''est lentement devenu ma passion à temps plein.", "choices": [{"text": "That''s inspiring — was it scary to make that leap?", "text_fr": "C''est inspirant — c''était effrayant de faire ce saut ?", "next": "n3"}]}, "n3": {"speaker": "artist", "text": "It really is here. Do you create anything yourself, or just appreciate from afar?", "text_fr": "C''est vraiment le cas ici. Vous créez quelque chose vous-même, ou vous appréciez juste de loin ?", "choices": [{"text": "I dabble in photography, actually. Nothing as impressive as this though.", "text_fr": "Je m''essaie à la photographie, en fait. Rien d''aussi impressionnant que ça par contre.", "next": "n4"}, {"text": "Not really, I''ve always admired art but never tried creating it myself.", "text_fr": "Pas vraiment, j''ai toujours admiré l''art mais jamais essayé d''en créer moi-même.", "next": "n4b"}]}, "n4": {"speaker": "artist", "text": "Photography is definitely an art form! What do you usually shoot?", "text_fr": "La photographie est définitivement une forme d''art ! Vous photographiez généralement quoi ?", "choices": [{"text": "Mostly landscapes and street scenes, whatever catches my eye.", "text_fr": "Surtout des paysages et des scènes de rue, tout ce qui attire mon œil.", "next": "n5"}]}, "n4b": {"speaker": "artist", "text": "You should try sometime! Art doesn''t have to be perfect, just genuine.", "text_fr": "Vous devriez essayer un jour ! L''art n''a pas besoin d''être parfait, juste sincère.", "choices": [{"text": "That''s a really encouraging way to think about it, thank you.", "text_fr": "C''est une façon vraiment encourageante d''y penser, merci.", "next": "n5"}]}, "n5": {"speaker": "artist", "text": "I love that. This festival is actually a perfect place to start, so much inspiration around.", "text_fr": "J''adore ça. Ce festival est en fait un endroit parfait pour commencer, tellement d''inspiration autour.", "choices": [{"text": "You''ve convinced me, I might actually give it a try this weekend.", "text_fr": "Vous m''avez convaincu, je pourrais vraiment essayer ce week-end.", "next": "end_inspired"}]}, "end_inspired": {"speaker": "artist", "text": "That makes my day! Come back and show me if you do, I''d love to see it.", "text_fr": "Ça fait ma journée ! Revenez me montrer si vous le faites, j''aimerais bien voir ça.", "end": true, "ending_label": "Une conversation inspirante avec un artiste 🎨✨"}}}'::jsonb, is_playable = true
where title = 'Discuter avec un artiste local'
  and theme_id = (select id from scenario_themes where position = 11 and language_id = (select id from languages where code = 'en'));
